sqlMap.select:
SELECT T.DEPTNO, SG.CONTENT AS DEPT_NAME, T.PARENT_DEPT_NO, T.dept_level DEPTH FROM (SELECT * FROM HR_DEPARTMENT HD WHERE 1 = 1
HD.CPNY_ID = #CPNY_ID:VARCHAR#
) T, HR_DEPARTMENT_NAME SG WHERE T.DEPTNO = SG.DEPTNO(+) AND SG.LANGUAGE(+) = #interLanguage:VARCHAR# START WITH T.dept_level = 1 CONNECT BY PRIOR T.DEPTNO = T.PARENT_DEPT_NO ORDER SIBLINGS BY T.ORDERNO
